package glitch

import data.glitch_lib

# Weak encryption algorithms
weak_algorithms := {"des", "3des", "rc4", "rc2", "md5", "sha1", "md4", "sha-1", "sslv2", "sslv3", "tlsv1.0", "tlsv1.1"}

# Weak cipher suites
weak_ciphers := {"rc4", "des", "3des", "ecb", "cbc", "null"}

# Algorithm attribute names
algorithm_attrs := {"cipher", "encryption_algorithm", "kms_key_spec", "key_algorithm", "algorithm", "ssl_policy", "security_policy", "tls_version", "minimum_protocol_version", "protocol", "signature_algorithm", "signing_algorithm", "sse_algorithm", "hash_algorithm", "digest_algorithm"}

# Key size attribute names
key_size_attrs := {"key_size", "key_length", "bits", "modulus_size", "rsa_key_size", "private_key_size", "rsa_bits", "key_bit_size"}

# Key spec attribute names
key_spec_attrs := {"key_spec", "customer_master_key_spec", "key_usage", "kms_key_spec"}

# Iteration attribute names
iteration_attrs := {"iterations", "rounds", "iteration_count", "pbkdf2_iterations"}

# Encryption/sensitive context attributes
encryption_context_attrs := {"encryption_enabled", "encrypted", "kms_managed", "aws_managed_key", "volume_encryption", "encryption_at_rest", "sse_enabled", "tls_enabled", "ssl_enabled"}

# Sensitive data type indicators
sensitive_indicators := {"password", "secret", "credential", "private_key", "sensitive", "api_key", "access_key", "token", "cert"}

# Check if string contains weak algorithm (case insensitive)
contains_weak_algorithm(str) {
    lower := lower(str)
    weak := weak_algorithms[_]
    contains(lower, weak)
}

# Check if string contains weak cipher (case insensitive)
contains_weak_cipher(str) {
    lower := lower(str)
    weak := weak_ciphers[_]
    contains(lower, weak)
}

# Check for weak TLS/SSL protocol
weak_protocol(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    weak_protocols := {"sslv2", "sslv3", "tlsv1.0", "tlsv1.1", "tls1.0", "tls1.1"}
    lower_val == weak_protocols[_]
} else {
    value.ir_type == "String"
    contains_weak_protocol(value.value)
}

contains_weak_protocol(str) {
    lower := lower(str)
    patterns := {"tlsv1.0", "tlsv1.1", "sslv2", "sslv3", "tls 1.0", "tls 1.1"}
    contains(lower, patterns[_])
}

# Get string value from various node types
get_string_value(node) = value {
    node.ir_type == "String"
    value := node.value
}

get_string_value(node) = value {
    node.ir_type == "VariableReference"
    value := node.value
}

# Check if value represents a number below threshold
is_below_threshold(node, threshold) {
    node.ir_type == "Integer"
    node.value < threshold
} else {
    node.ir_type == "String"
    num := to_number(node.value)
    num < threshold
}

# Check for weak key size based on algorithm context
weak_key_size(attr_name, value, context) {
    key_size_attrs[_] == attr_name
    is_below_threshold(value, 2048)
    contains(lower(context), "rsa")
} else {
    key_size_attrs[_] == attr_name
    is_below_threshold(value, 128)
    contains(lower(context), "aes")
} else {
    key_size_attrs[_] == attr_name
    is_below_threshold(value, 128)
    not contains(lower(context), "rsa")
    not contains(lower(context), "aes")
}

# Recursive check for weak algorithms in nested structures
has_weak_algorithm_in_value(node) {
    node.ir_type == "String"
    contains_weak_algorithm(node.value)
} else {
    node.ir_type == "Array"
    val := node.value[_]
    has_weak_algorithm_in_value(val)
} else {
    node.ir_type == "Hash"
    kv := node.value[_]
    has_weak_algorithm_in_value(kv.key)
} else {
    node.ir_type == "Hash"
    kv := node.value[_]
    has_weak_algorithm_in_value(kv.value)
}

# Check for weak cipher in nested structures
has_weak_cipher_in_value(node) {
    node.ir_type == "String"
    contains_weak_cipher(node.value)
} else {
    node.ir_type == "Array"
    val := node.value[_]
    has_weak_cipher_in_value(val)
}

# Check for low iterations
low_iterations(node) {
    iteration_attrs[_] == node.name
    is_below_threshold(node.value, 10000)
}

# Main detection: weak encryption algorithm configuration
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check algorithm attributes for weak algorithms
    algorithm_attrs[_] == attr.name
    has_weak_algorithm_in_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak or deprecated encryption algorithm - Avoid using weak encryption algorithms like DES, 3DES, RC4, MD5, SHA1. (CWE-326)"
    }
}

# Detection: weak TLS/SSL protocol version
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check protocol version fields
    protocol_attrs := {"tls_version", "minimum_protocol_version", "ssl_policy", "security_policy", "protocol"}
    protocol_attrs[_] == attr.name
    weak_protocol(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak TLS/SSL protocol version - Avoid using deprecated protocols like TLSv1.0, TLSv1.1, SSLv3. (CWE-326)"
    }
}

# Detection: weak cipher suites
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check cipher suite attributes
    cipher_attrs := {"cipher_suites", "allowed_ciphers", "ciphers", "ssl_policy", "security_policy"}
    cipher_attrs[_] == attr.name
    has_weak_cipher_in_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak cipher suites - Avoid using weak ciphers like RC4, DES, 3DES, ECB. (CWE-326)"
    }
}

# Detection: insufficient key size
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Find algorithm context for key size check
    alg_attr := attrs[_]
    alg_attr.name == "algorithm"

    key_size_attrs[_] == attr.name
    is_below_threshold(attr.value, 2048)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Insufficient encryption key size - Use key sizes of at least 2048 bits for RSA or 128 bits for symmetric encryption. (CWE-326)"
    }
}

# Detection: low iteration count for password hashing
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for password/secret hash context with low iterations
    low_iterations(attr)

    # Verify context is password-related
    context_attrs := {"password", "secret", "hash", "pbkdf2", "bcrypt", "scrypt"}
    ctx_attr := attrs[_]
    contains(lower(ctx_attr.name), context_attrs[_])

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Insufficient iteration count for password hashing - Use at least 10000 iterations for PBKDF2 or equivalent work factor. (CWE-326)"
    }
}

# Detection: sensitive data with weak encryption context
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for sensitive resource types
    lower_type := lower(node.type)
    contains(lower_type, sensitive_indicators[_])

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for weak algorithm in encryption context
    encryption_context_attrs[_] == attr.name
    attr.value.ir_type == "Boolean"
    attr.value.value == true

    weak_attr := attrs[_]
    algorithm_attrs[_] == weak_attr.name
    has_weak_algorithm_in_value(weak_attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": weak_attr,
        "path": parent.path,
        "description": "Weak encryption used for sensitive data - Strong encryption is required when handling passwords, keys, or credentials. (CWE-326)"
    }
}

# Detection: RSA key generation with insufficient key size
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for key generation resources
    lower_type := lower(node.type)
    contains(lower_type, "key")

